import { S3Client, PutObjectCommand, DeleteBucketCommand } from "@aws-sdk/client-s3";
import { checkpoint, restore } from "@tigrisdata/agent-kit";
import { writeFileSync } from "fs";
import { join } from "path";

const BUCKET_NAME = "pipeline-state";
const OBJECT_KEY = "v1.txt";
const FORK_NAME = "rollback-recovery";
const OUTPUT_FILE = "/home/user/chained-ckpt/recovery.json";

const s3 = new S3Client({
  endpoint: "REDACTED",
  region: "REDACTED",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});

async function run() {
  try {
    // 1. Upload v1
    console.log("Uploading v1.txt (version=1)...");
    await s3.send(new PutObjectCommand({
      Bucket: BUCKET_NAME,
      Key: OBJECT_KEY,
      Body: Buffer.from("version=1", "utf-8"),
    }));

    // 2. Checkpoint
    console.log("Taking checkpoint 'before-mutation'...");
    const { data: ckpt, error: ckptError } = await checkpoint(BUCKET_NAME, { name: "before-mutation" });
    if (ckptError) {
      console.error("Checkpoint error:", ckptError);
      process.exit(1);
    }
    const snapshotId = ckpt.snapshotId;
    console.log(`Checkpoint taken. snapshotId: ${snapshotId}`);

    // 3. Mutate
    console.log("Mutating v1.txt (version=2)...");
    await s3.send(new PutObjectCommand({
      Bucket: BUCKET_NAME,
      Key: OBJECT_KEY,
      Body: Buffer.from("version=2", "utf-8"),
    }));

    // 4. Restore
    console.log(`Restoring checkpoint ${snapshotId} to fork ${FORK_NAME}...`);
    const { data: restored, error: restoreError } = await restore(BUCKET_NAME, snapshotId, { forkName: FORK_NAME });
    if (restoreError) {
      console.error("Restore error:", restoreError);
      process.exit(1);
    }
    const recoveryBucket = restored.bucket;
    console.log(`Restored to bucket: ${recoveryBucket}`);

    // Write recovery.json
    writeFileSync(OUTPUT_FILE, JSON.stringify({ recoveryBucket }, null, 2));
    console.log(`Wrote ${OUTPUT_FILE}`);

    // 5. Tear down the recovery fork
    console.log(`Deleting recovery fork bucket: ${recoveryBucket}...`);
    await s3.send(new DeleteBucketCommand({
      Bucket: recoveryBucket,
    }));
    console.log("Recovery fork deleted.");

    process.exit(0);
  } catch (err) {
    console.error("Unexpected error:", err);
    process.exit(1);
  }
}

run();

